/* ============================================================
   HELPERS
   ============================================================ */
const $  = id => document.getElementById(id);
const fmt = (v, d=2) => (v===null||isNaN(v)) ? '—' : (+v).toFixed(d);

function batState(pct, sinDatos) {
  if (sinDatos) return 'no-data';
  if (pct >= CFG.BAT_NORMAL) return 'normal';
  if (pct >= CFG.BAT_WARN)   return 'warning';
  return 'critical';
}

function batLabel(estado) {
  return { cargando:'Cargando', completa:'Carga completa', descargando:'Descargando', critica:'Crítica', sin_datos:'Sin datos' }[estado] || 'Sin datos';
}

function timeFmt(min) {
  if (!min || min<=0) return '—';
  const h = Math.floor(min/60), m = min%60;
  if (!h) return `~${m}m`;
  if (!m) return `~${h}h`;
  return `~${h}h ${m}m`;
}

function applyState(el, st) {
  if (!el) return;
  ['state-normal','state-warning','state-critical','state-no-data'].forEach(c=>el.classList.remove(c));
  el.classList.add(`state-${st}`);
}

/* ============================================================
   NAVEGACIÓN DE PANTALLAS
   ============================================================ */
function navTo(screenId) {
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  const el = $(screenId);
  if (el) { el.classList.add('active'); window.scrollTo(0,0); }
  S.screen = screenId;
}

/* ============================================================
   INIT ASSETS — inyectar imágenes
   ============================================================ */
function initAssets() {
  /* Logo en todas las pantallas */
  ['inicio-logo','auth-logo','sidebar-logo-img','topbar-logo'].forEach(id => {
    const el = $(id); if (el) el.src = LOGO_SRC;
  });
  /* Fondo fotográfico en P1 y P2 */
  ['screen-inicio','screen-auth'].forEach(id => {
    const el = $(id);
    if (el) el.style.backgroundImage = `url(${BG_SRC})`;
  });
}

/* ============================================================
   P1 — INICIO PÚBLICO
   ============================================================ */
function initInicio() {
  const data = S.data || BASE_DATA;
  const dot = $('inicio-dot');
  const stTx = $('inicio-status-text');
  if (dot && stTx) {
    if (data.esp32_online) { dot.classList.remove('offline'); stTx.textContent = 'Sistema activo · Kiosco UTCJJ'; }
    else                   { dot.classList.add('offline');    stTx.textContent = 'Sistema sin conexión'; }
  }
  const pctEl = $('inicio-bat-pct');
  if (pctEl) pctEl.textContent = data.esp32_online ? `${Math.round(data.bateria_pct)}%` : '—';
}

/* ============================================================
   P2 — AUTH
   ============================================================ */
function initAuth() {
  $('btn-registrar').onclick = () => {
    const nombre = $('reg-nombre').value.trim();
    const usuario = $('reg-usuario').value.trim();
    const pass = $('reg-pass').value.trim();
    if (!nombre || !usuario || !pass) {
      [ ['reg-nombre',nombre], ['reg-usuario',usuario], ['reg-pass',pass] ]
        .forEach(([id,v]) => {
          if (!v) { const el=$(id); el.style.outline='1px solid var(--red)'; setTimeout(()=>{el.style.outline=''},1500); }
        });
      return;
    }
    navTo('screen-dashboard');
    initDashboard();
  };
  $('btn-login').onclick = () => {
    const usuario = $('log-usuario').value.trim();
    const pass = $('log-pass').value.trim();
    if (!usuario || !pass) {
      [ ['log-usuario',usuario], ['log-pass',pass] ]
        .forEach(([id,v]) => {
          if (!v) { const el=$(id); el.style.outline='1px solid var(--red)'; setTimeout(()=>{el.style.outline=''},1500); }
        });
      return;
    }
    navTo('screen-dashboard');
    initDashboard();
  };
}

/* ============================================================
   DASHBOARD — SETUP
   ============================================================ */
function initDashboard() {
  renderUserInfo();
  buildTabs();
  buildSidebarNav();
  poll();
  S.pollTimer = setInterval(poll, CFG.POLL_MS);
}

function renderUserInfo() {
  const av = $('topbar-avatar'); if (av) av.textContent = USER.iniciales;
  const un = $('topbar-username'); if (un) un.textContent = USER.nombre;
}

/* ============================================================
   TABS
   ============================================================ */
function buildTabs() {
  const tabs = USER.rol==='administrador' ? TABS_ADMIN : TABS_USER;
  const nav = $('nav-tabs');
  if (!nav) return;
  nav.innerHTML = '';
  tabs.forEach(t => {
    const btn = document.createElement('button');
    btn.className = `nav-tab${S.tab===t.id?' active':''}`;
    btn.id = `nav-tab-${t.id}`;
    btn.type = 'button';
    btn.textContent = t.label;
    btn.onclick = () => switchTab(t.id);
    nav.appendChild(btn);
  });
}

function switchTab(id) {
  if (S.tab === id) return;
  S.tab = id;
  document.querySelectorAll('.nav-tab').forEach(b => b.classList.remove('active'));
  const btn = $(`nav-tab-${id}`); if (btn) btn.classList.add('active');
  document.querySelectorAll('.sidebar-nav-btn').forEach(b => b.classList.remove('active'));
  const sb = $(`snav-${id}`); if (sb) sb.classList.add('active');
  document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
  const panel = $(`panel-${id}`); if (panel) panel.classList.add('active');
  if (id==='historial')    renderHistorial();
  if (id==='dispositivos') renderDispositivos();
}

/* ============================================================
   SIDEBAR
   ============================================================ */
function buildSidebarNav() {
  const tabs = USER.rol==='administrador' ? TABS_ADMIN : TABS_USER;
  const nav = $('sidebar-nav');
  if (!nav) return;
  nav.innerHTML = '';
  const ICONS = {
    bateria:     '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><rect x="2" y="7" width="18" height="11" rx="2"/><path d="M22 11v3"/></svg>',
    generacion:  '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>',
    alertas:     '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/></svg>',
    historial:   '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>',
    dispositivos:'<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><rect x="2" y="3" width="20" height="14" rx="2"/><line x1="8" y1="21" x2="16" y2="21"/><line x1="12" y1="17" x2="12" y2="21"/></svg>',
  };
  tabs.forEach(t => {
    const btn = document.createElement('button');
    btn.id = `snav-${t.id}`;
    btn.className = `sidebar-nav-btn${S.tab===t.id?' active':''}`;
    btn.type = 'button';
    btn.innerHTML = `${ICONS[t.id]||''}<span>${t.label}</span>`;
    btn.onclick = () => { switchTab(t.id); toggleDrawer(); };
    nav.appendChild(btn);
  });
}

function toggleDrawer() {
  S.sidebar = !S.sidebar;
  const sb = $('sidebar'), ov = $('sidebar-overlay'), hb = $('btn-hamburger');
  if (!sb||!ov||!hb) return;
  sb.classList.toggle('open', S.sidebar);
  ov.classList.toggle('visible', S.sidebar);
  hb.classList.toggle('open', S.sidebar);
  hb.setAttribute('aria-expanded', S.sidebar);
  sb.setAttribute('aria-hidden', !S.sidebar);
  document.body.style.overflow = S.sidebar ? 'hidden' : '';
}

/* ============================================================
   POLLING CYCLE
   ============================================================ */
function poll() {
  if (CFG.USE_API) {
    fetch(CFG.API_URL, { headers:{ Authorization:`Bearer ${localStorage.getItem('sylphen_token')||''}` } })
      .then(r=>r.json()).then(d=>actualizarDashboard(d))
      .catch(()=>actualizarDashboard({...BASE_DATA,esp32_online:false}));
  } else {
    actualizarDashboard(simVariation());
  }
}

function simVariation() {
  const d = () => (Math.random()-.5)*.08;
  const v = Math.min(CFG.V_MAX, Math.max(CFG.V_CRIT, +(BASE_DATA.voltaje+d()*.3).toFixed(2)));
  const c = Math.max(0, +(BASE_DATA.corriente+d()).toFixed(2));
  return { ...BASE_DATA, voltaje:v, corriente:c, potencia:+(v*c).toFixed(2), lectura_seg:Math.floor(Math.random()*9)+1 };
}

/* ============================================================
   actualizarDashboard()
   ============================================================ */
function actualizarDashboard(data) {
  S.data = data;
  const sin = !data.esp32_online;
  renderTopbarStatus(data.esp32_online, data.alertas_no_leidas);
  renderBattery(data, sin);
  renderGeneration(data, sin);
  renderAlerts(data.alertas||[]);
  renderCriticalBanner(data.alertas||[]);
  initInicio();
}

/* ============================================================
   renderBattery()
   ============================================================ */
function renderBattery(data, sin) {
  const pct  = sin ? null : data.bateria_pct;
  const st   = batState(pct||0, sin);
  const hero = document.querySelector('.battery-hero');
  if (hero) applyState(hero, st);

  const pctEl = $('bat-pct');
  if (pctEl) {
    pctEl.textContent = sin ? '—' : Math.round(pct);
    applyState(pctEl, st);
  }

  const badge = $('bat-badge');
  if (badge) {
    badge.textContent = sin ? 'Sin datos' : batLabel(data.bateria_estado);
    applyState(badge, st);
  }

  const bar = $('bat-bar');
  if (bar) {
    bar.style.width = sin ? '100%' : `${Math.min(100,Math.max(0,pct))}%`;
    applyState(bar, st);
  }

  const bv = $('bat-voltage');    if (bv)  bv.textContent  = sin ? '— V' : `${fmt(data.voltaje)} V`;
  const bt = $('bat-time');
  if (bt) {
    if (sin || data.bateria_estado==='completa') bt.textContent = data.bateria_estado==='completa' ? 'Carga completa' : '—';
    else bt.textContent = `${timeFmt(data.bateria_tiempo_min)} para ${data.bateria_estado==='descargando'?'agotarse':'completar'}`;
  }
  const br = $('bat-reading');    if (br)  br.textContent  = sin ? 'Sin señal del ESP32' : `hace ${data.lectura_seg}s`;

  renderDashAlerts(data.alertas||[]);
}

/* ============================================================
   renderAlerts() — lista completa tab Alertas
   ============================================================ */
function renderAlerts(alertas) {
  renderDashAlerts(alertas);
  const list = $('alerts-full-list');
  if (!list) return;
  const filtered = S.filter==='todas' ? alertas : alertas.filter(a=>a.tipo===S.filter);
  list.innerHTML = '';
  if (!filtered.length) {
    list.innerHTML = '<p class="alerts-empty">Sin alertas en esta categoría</p>';
    return;
  }
  filtered.forEach(a => {
    const row = document.createElement('div');
    row.className = 'alert-row';
    row.innerHTML = `
      <div class="alert-dot ${a.tipo}"></div>
      <div class="alert-body">
        <p class="alert-title">${a.titulo}</p>
        <p class="alert-desc">${a.desc}</p>
      </div>
      <span class="alert-time">${a.tiempo}</span>`;
    list.appendChild(row);
  });
}

function renderDashAlerts(alertas) {
  const list = $('dash-alerts-list');
  if (!list) return;
  const show = alertas.slice(0,3);
  list.innerHTML = '';
  if (!show.length) {
    list.innerHTML = '<p class="alerts-empty">Sin alertas recientes</p>';
    return;
  }
  show.forEach(a => {
    const row = document.createElement('div');
    row.className = 'alert-row';
    row.innerHTML = `
      <div class="alert-dot ${a.tipo}"></div>
      <div class="alert-body">
        <p class="alert-title">${a.titulo}</p>
        <p class="alert-desc">${a.desc}</p>
      </div>
      <span class="alert-time">${a.tiempo}</span>`;
    list.appendChild(row);
  });
}

/* ============================================================
   renderGeneration()
   ============================================================ */
function renderGeneration(data, sin) {
  const wEl = $('gen-watts'); if (wEl) wEl.textContent = sin ? '—' : fmt(data.potencia,1);
  const gb  = $('gen-badge');
  if (gb) {
    gb.textContent = sin ? 'Sin datos' : (data.potencia>0?'Activo':'Sin generación');
    applyState(gb, sin?'no-data':(data.potencia>0?'normal':'warning'));
  }
  const kEl = $('gen-kwh'); if (kEl) kEl.textContent = sin ? '—' : fmt(data.energia_hoy_kwh);
  const vEl = $('gen-volt'); if (vEl) vEl.textContent = sin ? '—' : fmt(data.voltaje);
  const ksub = $('gen-kwh-sub');
  if (ksub) {
    const p = data.var_energia_pct;
    ksub.textContent = p>0 ? `↑ +${p}% vs ayer` : p<0 ? `↓ ${p}% vs ayer` : 'Igual que ayer';
    ksub.className = `gen-card-sub ${p>0?'up':p<0?'down':''}`;
  }
  renderBarChart();
}

/* ============================================================
   renderBarChart() — SVG
   ============================================================ */
function renderBarChart() {
  const svg = $('bar-chart');
  const labelsEl = $('chart-labels');
  if (!svg || !labelsEl) return;

  const data = CHART_HOURS;
  const maxW = Math.max(...data.map(d=>d.w), 0.1);
  const W = 480, H = 100, pad = 2;
  const barW = (W - pad*(data.length+1)) / data.length;

  svg.innerHTML = '';
  data.forEach((d, i) => {
    const barH = (d.w / maxW) * (H - 12);
    const x = pad + i*(barW+pad);
    const y = H - barH;

    const rect = document.createElementNS('http://www.w3.org/2000/svg','rect');
    rect.setAttribute('x', x.toFixed(1));
    rect.setAttribute('y', y.toFixed(1));
    rect.setAttribute('width', barW.toFixed(1));
    rect.setAttribute('height', barH.toFixed(1));
    rect.setAttribute('rx', '2');
    rect.setAttribute('fill', '#1D9E75');
    rect.setAttribute('opacity', i === data.length-1 ? '1' : '0.65');
    svg.appendChild(rect);
  });

  labelsEl.innerHTML = '';
  data.forEach(d => {
    const span = document.createElement('span');
    span.className = 'chart-lbl';
    span.textContent = d.h;
    labelsEl.appendChild(span);
  });
}

/* ============================================================
   renderHistorial()
   ============================================================ */
function renderHistorial() {
  const tbody = $('hist-tbody');
  if (!tbody) return;
  tbody.innerHTML = '';
  HIST_DATA.forEach(row => {
    const stCls = {ok:'status-ok',warn:'status-warn',err:'status-err'}[row.estado]||'';
    const stLabel = {ok:'Normal',warn:'Advertencia',err:'Error'}[row.estado]||'—';
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${row.fecha}</td>
      <td>${row.kwh} kWh</td>
      <td>${row.v} V</td>
      <td><span class="${stCls}">${stLabel}</span></td>`;
    tbody.appendChild(tr);
  });
}

/* ============================================================
   renderDispositivos()
   ============================================================ */
function renderDispositivos() {
  const grid = $('devices-grid');
  if (!grid) return;
  const data = S.data || BASE_DATA;
  const devs = [
    { name:'Arduino Uno',  icon:devIcon('cpu'),     online:data.esp32_online, detail:'Lectura INA226 · I²C' },
    { name:'ESP32',        icon:devIcon('wifi'),    online:data.esp32_online, detail:`WiFi · Envío cada ${data.lectura_seg||8}s` },
    { name:'Sensor INA226',icon:devIcon('activity'),online:data.esp32_online, detail:`${fmt(data.voltaje)} V · ${fmt(data.corriente,2)} A` },
    { name:'Batería 18650',icon:devIcon('battery'), online:true,             detail:`${Math.round(data.bateria_pct||0)}% · ${fmt(data.voltaje)} V` },
  ];
  grid.innerHTML = '';
  devs.forEach(d => {
    const card = document.createElement('div');
    const st = d.online?'online':'offline';
    card.className = `device-card ${st}`;
    card.innerHTML = `
      <div class="device-icon-wrap ${st}">${d.icon}</div>
      <p class="device-name">${d.name}</p>
      <span class="device-status-badge ${st}">${d.online?'En línea':'Sin respuesta'}</span>
      <p class="device-detail">${d.detail}</p>`;
    grid.appendChild(card);
  });
  const ts = $('devices-timestamp');
  if (ts) ts.textContent = `Última actualización hace ${data.lectura_seg||'—'}s`;
}

function devIcon(type) {
  const icons = {
    cpu:     '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><rect x="4" y="4" width="16" height="16" rx="2"/><rect x="9" y="9" width="6" height="6"/><line x1="9" y1="1" x2="9" y2="4"/><line x1="15" y1="1" x2="15" y2="4"/><line x1="9" y1="20" x2="9" y2="23"/><line x1="15" y1="20" x2="15" y2="23"/><line x1="20" y1="9" x2="23" y2="9"/><line x1="20" y1="14" x2="23" y2="14"/><line x1="1" y1="9" x2="4" y2="9"/><line x1="1" y1="14" x2="4" y2="14"/></svg>',
    wifi:    '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M5 12.55a11 11 0 0 1 14.08 0"/><path d="M1.42 9a16 16 0 0 1 21.16 0"/><path d="M8.53 16.11a6 6 0 0 1 6.95 0"/><line x1="12" y1="20" x2="12.01" y2="20"/></svg>',
    activity:'<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>',
    battery: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><rect x="2" y="7" width="18" height="11" rx="2"/><path d="M22 11v3"/><line x1="6" y1="11" x2="6" y2="14"/><line x1="10" y1="11" x2="10" y2="14"/></svg>',
  };
  return icons[type]||'';
}

/* ============================================================
   renderTopbarStatus() & renderCriticalBanner()
   ============================================================ */
function renderTopbarStatus(online, noLeidas) {
  const dot = $('topbar-dot'), txt = $('topbar-status-text');
  if (dot) dot.classList.toggle('offline', !online);
  if (txt) txt.textContent = online ? 'En línea' : 'Sin conexión';
  const badge = $('bell-badge');
  if (badge) { badge.textContent = noLeidas; badge.classList.toggle('hidden', !noLeidas); }
}

function renderCriticalBanner(alertas) {
  if (S.bannerDismissed) return;
  const banner = $('critical-banner');
  const txt    = $('banner-text');
  const crit   = alertas.find(a=>a.tipo==='critica');
  if (banner) banner.classList.toggle('hidden', !crit);
  if (txt && crit) txt.textContent = `${crit.titulo}: ${crit.desc}`;
}

/* ============================================================
   EXPORT CSV (simulado)
   ============================================================ */
function exportCSV() {
  const rows = [['Fecha','Energía (kWh)','Voltaje (V)','Estado'], ...HIST_DATA.map(r=>[r.fecha,r.kwh,r.v,r.estado])];
  const csv = rows.map(r=>r.join(',')).join('\n');
  const a = document.createElement('a');
  a.href = 'data:text/csv;charset=utf-8,' + encodeURIComponent(csv);
  a.download = 'sylphen_historial.csv';
  a.click();
}

/* ============================================================
   EVENT LISTENERS
   ============================================================ */
function setupEvents() {
  /* P1 */
  $('btn-inicio').onclick = () => navTo('screen-auth');

  /* Sidebar */
  $('btn-hamburger').onclick = toggleDrawer;
  $('sidebar-overlay').onclick = toggleDrawer;
  $('btn-logout').onclick = () => {
    if (S.pollTimer) clearInterval(S.pollTimer);
    navTo('screen-inicio');
    initInicio();
  };

  /* Campana → alertas */
  $('btn-bell').onclick = () => switchTab('alertas');

  /* Ver todas las alertas */
  $('btn-ver-alertas').onclick = () => switchTab('alertas');

  /* Banner */
  $('btn-banner-close').onclick  = () => { S.bannerDismissed=true; $('critical-banner').classList.add('hidden'); };
  $('btn-banner-alerts').onclick = () => { S.bannerDismissed=true; $('critical-banner').classList.add('hidden'); switchTab('alertas'); };

  /* Filtros alertas */
  document.querySelectorAll('.filter-pill').forEach(btn => {
    btn.onclick = () => {
      S.filter = btn.dataset.filter;
      document.querySelectorAll('.filter-pill').forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      if (S.data) renderAlerts(S.data.alertas||[]);
    };
  });

  /* Export CSV */
  $('btn-export').onclick = exportCSV;

  /* Escape cierra sidebar */
  document.addEventListener('keydown', e => { if (e.key==='Escape'&&S.sidebar) toggleDrawer(); });
}

/* ============================================================
   INIT
   ============================================================ */
document.addEventListener('DOMContentLoaded', () => {
  initAssets();
  initAuth();
  setupEvents();
  initInicio();
  console.info('[Sylphen] Listo. Modo: datos simulados. Para API real: CFG.USE_API = true');
});
